hey <@U0CL0QSS929>
Could you please run the following two queries and share the output of each?

Each query will run for *5 minutes*.

*Query 1: Raw oplog read through mongos* ```const start = Math.floor(Date.now() / 1000) - 3600, began = Date.now();
let events = 0, pos = start;
const cs = db.getMongo().watch([], { startAtOperationTime: Timestamp({ t: start, i: 0 }) });
while (Date.now() - began &lt; 300000) {
  const doc = cs.tryNext();
  if (doc) { events++; pos = doc.clusterTime.getHighBits(); }
  else { const tok = cs.getResumeToken(); if (tok &amp;&amp; tok._data) pos = parseInt(tok._data.substr(2, 8), 16); }
}
cs.close();
const wall = (Date.now() - began) / 1000;
print(`raw: oplog_covered=${pos - start}s speed=${((pos - start) / wall).toFixed(2)}x events=${events} events_per_sec=${(events / wall).toFixed(1)}`);``` 
*Query 2: OLake-style read of one collection* ```const start = Math.floor(Date.now() / 1000) - 3600, began = Date.now();
let events = 0, pos = start;
db.getMongo().setReadConcern("majority");
const cs = db.getSiblingDB("juno_v2_prod_money").generic_gv.watch(
  [{ $match: { operationType: { $in: ["insert", "update", "replace", "delete"] } } }],
  { startAtOperationTime: Timestamp({ t: start, i: 0 }), fullDocument: "updateLookup", fullDocumentBeforeChange: "whenAvailable", maxAwaitTimeMS: 2000 }
);
while (Date.now() - began &lt; 300000) {
  const doc = cs.tryNext();
  if (doc) { events++; pos = doc.clusterTime.getHighBits(); }
  else { const tok = cs.getResumeToken(); if (tok &amp;&amp; tok._data) pos = parseInt(tok._data.substr(2, 8), 16); }
}
cs.close();
const wall = (Date.now() - began) / 1000;
print(`olake: oplog_covered=${pos - start}s speed=${((pos - start) / wall).toFixed(2)}x events=${events} events_per_sec=${(events / wall).toFixed(1)}`);```

